    def areAnagrams(self, root1, root2):
        def level_order_traversal(root):
            if not root:
                return []
            result = []
            queue = [root]
            while queue:
                level_size = len(queue)
                level_values = []
                for _ in range(level_size):
                    node = queue.pop(0)
                    level_values.append(node.val)
                    if node.left:
                        queue.append(node.left)
                    if node.right:
                        queue.append(node.right)
                result.append(sorted(level_values))
            return result

        traversal1 = level_order_traversal(root1)
        traversal2 = level_order_traversal(root2)

        if len(traversal1) != len(traversal2):
            return 0

        for level1, level2 in zip(traversal1, traversal2):
            if level1 != level2:
                return 0

        return 1
